import {templates,stickers,designFor} from './flow-assets/catalog.js';
import {mountPhoneSelector,modelVariant} from './phone-models.js?v=36';
import {chooseSharing} from './sharing.js?v=33';
import {getProfile} from './profile-store.js?v=30';
const store=window.PopomoDesigns,root=document.querySelector('#community-main'),query=new URLSearchParams(location.search),isDetail=document.body.dataset.communityView==='detail'||/\/work-detail(?:\.html)?\/?$/.test(location.pathname);
let lang=window.PopomoLocale.get();
const t=(zh,en)=>lang==='en'?en:zh,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalog=await fetch('./flow-assets/data.json').then(r=>r.json());
const seedIds=['bloom','sunset','garden','ocean'];
function seed(id){const theme=templates.find(x=>x.id===id),d=designFor(id),m=catalog.models.find(x=>x.name==='iPhone 13 Pro')||catalog.models[0];return {id:'popomo-'+id,name:theme[lang==='en'?'en':'zh'],author:'POPOMO',model:m.name,phoneColor:'blue',source:'template',template:id,published:true,flowState:{model:m.name,brand:m.brand,phoneColor:'blue',template:id,background:d.background,layers:d.layers.map(l=>({...l,scale:1,origin:'preset',src:l.type==='sticker'?stickers.find(s=>s.id===l.asset)?.src:l.src})),editor:{source:'template',drafts:{},photoDraft:null,aiDraft:null}}};}
const loadImage=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src;});
async function artwork(design,m){if(!design.flowState?.layers)return design.cover||design.image;const c=document.createElement('canvas');c.width=m.width;c.height=m.height;const ctx=c.getContext('2d'),state=design.flowState;ctx.fillStyle=state.background||'#fff';ctx.fillRect(0,0,c.width,c.height);for(const l of state.layers){ctx.save();ctx.translate(l.x/100*c.width,l.y/100*c.height);ctx.rotate((l.rotation||0)*Math.PI/180);ctx.scale(l.scale||1,l.scale||1);if(l.type==='text'){ctx.fillStyle=l.color||'#100519';ctx.font=`600 ${l.size*.0015*c.width}px ${l.font==='sans'?'Arial':l.font==='hand'?'cursive':l.font==='mono'?'monospace':'Georgia'}`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(l.text,0,0);}else{const im=await loadImage(l.src),w=l.size/100*c.width;if(l.id==='photo-background'){const h=c.height,f=Math.max(w/im.width,h/im.height),sw=w/f,sh=h/f;ctx.drawImage(im,(im.width-sw)/2,(im.height-sh)/2,sw,sh,-w/2,-h/2,w,h);}else ctx.drawImage(im,-w/2,-w*im.height/im.width/2,w,w*im.height/im.width);}ctx.restore();}ctx.globalCompositeOperation='destination-in';ctx.drawImage(await loadImage(m.mask),0,0,c.width,c.height);ctx.globalCompositeOperation='source-over';ctx.drawImage(await loadImage(m.overlay),0,0,c.width,c.height);return c.toDataURL('image/webp',.85);}
let seeds=await Promise.all(seedIds.map(async id=>{const d=seed(id);d.cover=await artwork(d,modelVariant(catalog.models.find(m=>m.name===d.model),d.phoneColor));return d;}));
const all=()=>[...store.shared(),...seeds];
const own=()=>query.get('own')==='1'?store.list().find(d=>d.id===query.get('id')):null;
const current=()=>own()||all().find(d=>d.id===query.get('id'));
const heart='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 4.8a5.3 5.3 0 0 0-7.5 0L12 5.9l-1.1-1.1a5.3 5.3 0 0 0-7.5 7.5L12 21l8.6-8.7a5.3 5.3 0 0 0-.1-7.5Z"/></svg>';
function authorBadge(d){const candidate=d.authorAvatar||'./assets/avatars/avatar-1-v30.svg',avatar=/^(?:\.\/assets\/|data:image\/(?:png|jpeg|webp|gif);base64,|https:\/\/)/i.test(candidate)?candidate:'./assets/avatars/avatar-1-v30.svg';return `<div class="work-creator"><img class="work-creator-avatar" src="${esc(avatar)}" alt="" loading="lazy"><span class="work-creator-name">${esc(d.author||t('POPOMO 创作者','POPOMO creator'))}</span></div>`;}
function likeButton(d){return `<button class="work-like" data-like="${esc(d.id)}" aria-pressed="${store.liked(d.id)}" aria-label="${t('点赞','Like')} ${esc(d.name)}">${heart}<span>${store.liked(d.id)?'1':'0'}</span></button>`;}
function render(){lang=window.PopomoLocale?.get()||lang;document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelector('#flow-language').value=lang;if(isDetail){const d=current();document.title=t('作品详情','Design details')+' · POPOMO';if(!d){root.innerHTML=`<h1>${t('作品暂不可用','Design unavailable')}</h1><a class="tertiary" href="./works-center.html">${t('返回作品中心','Back to Works center')}</a>`;return;}const mine=!!own();root.innerHTML=`<a class="work-back" href="./${mine?'my-designs':'works-center'}.html">← ${mine?t('我的设计','My designs'):t('作品中心','Works center')}</a><section class="work-detail-layout"><div class="work-large"><img src="${esc(d.cover||d.image)}" alt="${esc(d.name)}"></div><div class="work-detail-info"><p class="work-kicker">MADE TO BE YOURS.</p><h1>${esc(d.name)}</h1>${authorBadge(d)}<span class="work-model-tag">${esc(d.model)}</span>${mine?`<p class="work-visibility">${d.published?t('已分享到作品中心','Shared in Works center'):t('私人草稿，仅自己可见','Private draft — only visible to you')}</p>`:''}<div class="work-detail-actions"><button class="primary" data-use="print">${t('去打印','Print this design')} ↗</button><button class="secondary" data-use="edit">${mine?t('继续设计','Keep designing'):t('复用设计','Use this design')} ↗</button></div><div class="work-detail-bottom">${d.published?likeButton(d):''}${mine?`<button class="tertiary" data-share>${d.published?t('管理分享','Manage sharing'):t('分享到作品中心','Share to Works center')}</button>`:''}</div><p class="community-error" role="alert"></p></div></section>`;root.querySelectorAll('[data-use]').forEach(b=>b.onclick=()=>mine?useOwn(d,b.dataset.use):choosePhone(d,b.dataset.use));root.querySelector('[data-share]')?.addEventListener('click',async()=>{const options=await chooseSharing(t);if(!options)return;try{store.save({...d,...options});render();}catch{showError();}});}else{document.title=t('作品中心','Works center')+' · POPOMO';root.innerHTML=`<header class="community-heading"><div><p class="work-kicker">CREATED. SHARED. MADE YOURS.</p><h1>${t('作品中心','Works center')}</h1><p>${t('看看大家的灵感，发现你的下一个手机壳。','A little inspiration from the community. Find your next case.')}</p></div><a class="secondary" href="./my-designs.html">${t('我的设计','My designs')} ↗</a></header><section class="community-grid" aria-label="${t('公开作品','Shared designs')}">${all().map(d=>`<article class="community-card" data-detail-id="${esc(d.id)}"><a class="community-cover" aria-label="${esc(t('查看作品详情：','View design: ')+d.name)}" href="./work-detail.html?id=${encodeURIComponent(d.id)}"><img src="${esc(d.cover||d.image)}" alt="${esc(d.name)}" loading="lazy"></a><div class="community-card-body"><a href="./work-detail.html?id=${encodeURIComponent(d.id)}"><h2>${esc(d.name)}</h2></a>${authorBadge(d)}<div class="community-card-meta"><span class="work-model-tag">${esc(d.model)}</span>${likeButton(d)}</div></div></article>`).join('')}</section>`;}root.querySelectorAll('[data-detail-id]').forEach(card=>card.addEventListener('click',e=>{if(e.target.closest('a,button,input,select'))return;location.href='./work-detail.html?id='+encodeURIComponent(card.dataset.detailId);}));bindLikes();}
function bindLikes(){root.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{try{store.toggleLike(b.dataset.like);const liked=store.liked(b.dataset.like);b.setAttribute('aria-pressed',String(liked));b.querySelector('span').textContent=liked?'1':'0';}catch{showError();}});}
function showError(){const e=root.querySelector('.community-error');if(e)e.textContent=t('暂时无法完成，请重试。','Could not complete this action. Please retry.');}
function fork(d,m,color){const s=d.flowState?structuredClone(d.flowState):null;if(s){s.editor={source:s.editor?.source||d.source||'template',drafts:{},photoDraft:null,aiDraft:null};s.model=m.name;s.brand=m.brand;s.phoneColor=color;delete s.savedDesignId;delete s.homeEntry;s.designName=d.name;}return {...d,id:crypto.randomUUID(),model:m.name,phoneColor:color,flowState:s,author:getProfile()?.nickname||t('你','You'),authorAvatar:getProfile()?.avatar||'./assets/avatars/avatar-1-v30.svg',published:false,sharingConsentAt:null,parentDesignId:d.id};}
function edit(d){if(d.flowState)d={...d,flowState:{...d.flowState,editor:{source:d.flowState.editor?.source||d.source||'template',drafts:{},photoDraft:null,aiDraft:null}}};const entry={...d,id:crypto.randomUUID(),designId:d.id,flowState:structuredClone(d.flowState)};sessionStorage.setItem('popomo-design-entry',JSON.stringify(entry));location.href='./customize.html?entry='+encodeURIComponent(entry.id)+'#design';}
function useOwn(d,intent){if(intent==='edit'){edit(d);return;}try{const order=window.PopomoOrders.create(d);location.href='./checkout.html?order='+encodeURIComponent(order.id);}catch{showError();}}
function choosePhone(d,intent){const dialog=document.createElement('dialog');dialog.className='community-phone-dialog';dialog.innerHTML=`<header><h2>${t('选择你的机型与颜色','Choose your phone & color')}</h2><button data-close aria-label="${t('关闭','Close')}">×</button></header><div data-picker></div><button class="primary" data-go>${intent==='print'?t('继续打印','Continue to print'):t('开始设计','Start designing')} →</button><p class="community-error" role="alert"></p>`;let selected=catalog.models.find(m=>m.name===d.model)||catalog.models[0],color=d.phoneColor||'blue';mountPhoneSelector(dialog.querySelector('[data-picker]'),{models:catalog.models,value:selected.name,color,t,onChange:(m,c)=>{selected=m;color=c;}});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.querySelector('[data-go]').onclick=async()=>{const b=dialog.querySelector('[data-go]');b.disabled=true;try{const copy=fork(d,selected,color);copy.cover=await artwork(copy,modelVariant(selected,color));copy.image=copy.cover;if(intent==='print'){const saved=store.save(copy),order=window.PopomoOrders.create(saved);location.href='./checkout.html?order='+encodeURIComponent(order.id);}else{const entry={...copy,id:crypto.randomUUID(),designId:undefined};sessionStorage.setItem('popomo-design-entry',JSON.stringify(entry));location.href='./customize.html?entry='+encodeURIComponent(entry.id)+'#design';}}catch{b.disabled=false;dialog.querySelector('.community-error').textContent=t('暂时无法打开，请重试。','Could not open. Please retry.');}};document.body.append(dialog);dialog.showModal();}
window.addEventListener('storage',render);render();

window.PopomoLocale.subscribe(()=>{lang=window.PopomoLocale.get();seeds=seeds.map(d=>({...d,name:templates.find(x=>'popomo-'+x.id===d.id)[lang==='en'?'en':'zh']}));render();});
